--
-- Un-freeze levels 81-85 (custom realm level cap). Generated by
-- client-resources/generate_85cap_sql.py - re-run it instead of editing by hand.
--
-- 1) Base stats / HP / mana for 81-85, extrapolated from each class's own 76-80 trend.
--    ObjectMgr::LoadPlayerInfo otherwise gap-fills these levels with the level-80 row
--    (and logs one error per missing level).
DELETE FROM `player_class_stats` WHERE `Level` BETWEEN 81 AND 85;

-- 2) XP required for 80-84, continuing the existing ~+16.6k/level slope.
--    Without these rows GetXPForLevel() returns 0 above level 79 (free levels).
DELETE FROM `player_xp_for_level` WHERE `Level` BETWEEN 80 AND 84;

-- 3) LFGDungeons overrides: raise the WotLK-era brackets to the realm cap so
--    LFGMgr::GetRandomAndSeasonalDungeons(level, expansion) matches them again
--    (it requires minlevel <= level <= maxlevel; every entry stopped at 80/83).
--    The client needs the same change in its own LFGDungeons.dbc - see
--    client-resources/generate_lfg_dungeon_dbc_patch.py.
DELETE FROM `lfgdungeons_dbc` WHERE `ID` IN (202, 203, 204, 206, 207, 208, 209, 214, 216, 218, 220, 225, 245, 251, 253, 255, 46, 159, 223, 224, 227, 237, 238, 239, 240, 243, 244, 246, 247, 248, 250, 257, 279, 280, 293, 294, 228, 229, 230, 231, 232, 233, 234, 235, 236, 205, 210, 211, 212, 213, 215, 217, 219, 221, 226, 241, 242, 249, 252, 254, 256, 261, 262);

-- 4) Random-dungeon rewards: extend the top reward row to the realm cap so
--    LFGMgr::GetRandomDungeonReward() resolves at 81-85 (it picks the first row whose
--    maxLevel >= player level).
DELETE FROM `lfg_dungeon_rewards` WHERE `maxLevel` = 85;
